/* The action is pinned to the bottom so a row of plans with different numbers of
 * features still lines its buttons up: a ragged row of CTAs reads as a mistake
 * and makes the plans hard to compare, which is the whole job of the row. */
.plan-card { display: flex; flex-direction: column; }
.plan-card-action { margin-block-start: auto; padding-block-start: var(--space-4); }

.plan-card-head { display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap; }

/* The recommended plan is outlined, not filled: a filled one turns the row into
 * one loud card and two grey ones, and the grey ones are still for sale. */
.plan-card[data-recommended] { border-color: var(--primary); }

.plan-card-price { display: flex; align-items: baseline; gap: var(--space-2); flex-wrap: wrap; }
.plan-card-amount { font-size: var(--font-2xl); font-weight: var(--font-weight-semibold); }
.plan-card-period { color: var(--muted-foreground); font-size: var(--font-sm); }
.plan-card-desc { color: var(--muted-foreground); font-size: var(--font-sm); }

.plan-card-features {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--font-sm);
}
.plan-card-features li { display: flex; align-items: flex-start; gap: var(--space-2); }
.plan-card-tick { flex: none; margin-block-start: var(--space-2xs); color: var(--success-emphasis); }

import './PlanCard.css'
import type { ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Badge } from '../Badge'
import { Card, CardTitle } from '../Card'
import { Icon } from '../Icon'

/* Monolithic because a pricing card is a fixed anatomy — name, price,
 * period, what you get, the action, and whether this is the one being
 * recommended — and the fixedness is what lets three of them stand in a row
 * and be compared. */
type Props = {
  name: string
  /** Already formatted, including the currency: this component does not know
   *  the locale, the currency or whether the number is per seat. */
  price: string
  /** What the price is per, e.g. "per month". */
  period?: string
  /* ReactNode: the same word means the same shape everywhere in this system,
   * and its neighbours already took one. Widened 2026-09-03; it is rendered
   * as content here, never put in an attribute. */
  description?: ReactNode
  features: string[]
  /** The one thing to do with this plan. A `<Button>`, usually. */
  action: ReactNode
  /** Marks the plan being steered toward. One per row, or it steers nowhere. */
  recommended?: boolean
  recommendedLabel?: string
  className?: string
}

/** One plan in a pricing row: what it is called, what it costs, what it includes
 *  and the single action that takes it. 
 *
 * Copy: the name is what the reader will call it afterwards, not a tier number.
 * Features are outcomes, not switches: "Everyone sees the same board", not
 * "Shared board: yes". The price says its period every time.
 */
export function PlanCard({
  name, price, period, description, features, action, recommended, recommendedLabel = 'Recommended', className,
}: Props) {
  return (
    <Card stretch className={cn('plan-card', className)} data-recommended={recommended || undefined}>
      <div className="plan-card-head">
        <CardTitle as="h3">{name}</CardTitle>
        {recommended && <Badge tone="primary" fill="soft">{recommendedLabel}</Badge>}
      </div>
      <p className="plan-card-price">
        <span className="plan-card-amount">{price}</span>
        {period && <span className="plan-card-period">{period}</span>}
      </p>
      {description && <p className="plan-card-desc">{description}</p>}
      {/* A list, not a stack of divs: how many things are included is part of
          what a plan is, and a screen reader should be able to say "6 items". */}
      <ul className="plan-card-features">
        {features.map((feature) => (
          <li key={feature}>
            <Icon name="check" className="plan-card-tick" />
            {feature}
          </li>
        ))}
      </ul>
      <div className="plan-card-action">{action}</div>
    </Card>
  )
}
